using UnityEngine;
using LWS.TruckBowling;
namespace LWS.TruckSports {
// Camera/input ownership is explicit. One match simulation serves all views and one root listener.
public sealed class SportsRallyViews:MonoBehaviour {
 public SportsEventSession session;public SportsExpansionSpectators retiredViews;public SportsEventCamera broadcast;public SportsEventCamera[] views;public SportsEventTruck[] trucks;public SportsChaosWeather weather;public Vector3 groundOffset=new Vector3(0,9,-19);public float groundLookAhead=8,groundFov=70;public int Humans{get;private set;}public readonly int[] owners=new int[4];readonly Quaternion[] headings=new Quaternion[4];public int Focus;public bool Replay;public int[] presentationGroups;
 public void Layout(int[] pairGroups=null){Humans=SportsCameraOptions.Select(session.setup,owners,pairGroups??(presentationGroups!=null&&presentationGroups.Length==session.setup.count?presentationGroups:null));broadcast.view.enabled=Humans==0;session.cameras=Humans==0?new[]{broadcast.view}:new Camera[Humans];for(int i=0;i<views.Length;i++){views[i].view.enabled=i<Humans;headings[i]=Quaternion.identity;if(i<Humans){views[i].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(Humans,i);session.cameras[i]=views[i].view;}}if(weather!=null){weather.vendor.AllowCameras.Clear();foreach(var c in session.cameras)weather.vendor.AllowCameras.Add(c);}}
 public void Follow(float dt,bool[] airborne=null,Vector3[] focusPoints=null){if(Replay)return;if(Humans==0){int slot=Mathf.Clamp(Focus,0,trucks.Length-1);var p=focusPoints==null?trucks[slot].body.position:focusPoints[slot];broadcast.Pose(p+Vector3.forward*8,new Vector3(0,16,-24),68);return;}for(int v=0;v<Humans;v++){if(retiredViews!=null&&retiredViews.OwnsView(v))continue;int slot=owners[v];var t=trucks[slot];var forward=Vector3.ProjectOnPlane(t.transform.forward,Vector3.up);if(forward.sqrMagnitude>.1f&&Vector3.Dot(t.transform.up,Vector3.up)>.35f&&(airborne==null||!airborne[slot]))headings[v]=Quaternion.Slerp(headings[v],Quaternion.LookRotation(forward),1-Mathf.Exp(-dt*3));var direction=headings[v]*Vector3.forward;bool flying=airborne!=null&&airborne[slot];var focus=(focusPoints==null?t.body.position:focusPoints[slot])+Vector3.up*.8f+direction*(flying?3:groundLookAhead);views[v].Pose(focus,headings[v]*(flying?new Vector3(0,13,-26):groundOffset),flying?74:groundFov);}}
 public void ReplayView(Vector3 focus,int angle,Vector3? offset=null){if(!Replay&&weather!=null){weather.vendor.AllowCameras.Clear();weather.vendor.AllowCameras.Add(broadcast.view);}Replay=true;broadcast.view.enabled=true;foreach(var v in views)v.view.enabled=false;broadcast.view.rect=new Rect(0,0,1,1);broadcast.Pose(focus,offset??(angle%3==0?new Vector3(18,12,-18):angle%3==1?new Vector3(-23,6,7):new Vector3(0,38,-5)),62);}
 public void Restore(){Replay=false;Layout();}
}
}
